import test from 'node:test';
import assert from 'node:assert/strict';
import {mkdtempSync,rmSync} from 'node:fs';
import {tmpdir} from 'node:os';
import {join} from 'node:path';
import {openStore} from '../server/store.mjs';
import {createService} from '../server/service.mjs';
import {createHandler} from '../server/index.mjs';
import {digest,codexPrompt} from '../server/codex-research.mjs';
import {assertDatabaseMode} from '../server/runtime.mjs';
import {createBackup} from '../server/backup.mjs';
import {rehearseRecovery} from '../server/recovery-rehearsal.mjs';
const config={binary:'/test/codex',model:'test-model',timeoutMs:1000},at='2026-10-03T00:00:00Z';
const quotes=['虚构甲公司拟收购乙公司，仍需批准。','虚构丙公司终止丁项目，原因待核实。'],body=quotes.join('')+'所有信息仅为合成流程样例，不构成独立证据。'.repeat(20);
const decomposition=()=>({events:quotes.map((quote,i)=>({title:`合成事项${i}`,actor:i?'虚构丙':'虚构甲',action:i?'终止':'拟收购',object:i?'丁项目':'乙公司',stage:'待核',eventTime:'未知',quote,quoteField:'body',boundaryReason:'不同主体和对象的两个具体事项',timeEvidence:{basis:'unknown',quote:'',quoteField:'none'},timeRole:'unknown'})),scopeNote:'仅为合成已提供材料，不代表完整',missingEvidence:['核实原始公告']});
function extraction(p,value=decomposition()){const rawOutput=JSON.stringify(value);return {status:'candidate',reviewStatus:'unreviewed',decomposition:value,rawOutput,trace:{model:config.model,inputHash:p.inputHash,outputHash:digest(rawOutput)}};}
function dossier(p){const v={sections:['facts','materiality','companies','scenarios','conditions'].map(id=>({id,title:id,paragraphs:[p.input.eventExtraction?.event.title||'来源整体的合成研究'],sourceIds:[]})),missingEvidence:['核实事项范围']},rawOutput=JSON.stringify(v);return {status:'candidate',reviewStatus:'unreviewed',...v,rawOutput,trace:{model:config.model,inputHash:p.inputHash,topicId:p.input.topicId,topicVersion:p.input.topicVersion,outputHash:digest(rawOutput)}};}
function fixture({path=':memory:',extractRunner=async p=>extraction(p),modelRunner=async p=>dossier(p),semanticRunner,enable=true}={}){
 let clock=Date.parse(at),extractCalls=0,modelCalls=0;const packets=[],store=openStore(path);assertDatabaseMode(store,'research');
 const service=createService(store,{mode:'research',modelConfig:config,now:()=>clock,...(semanticRunner?{semanticRunner}:{}),modelRunner:async p=>{modelCalls++;packets.push(p);return modelRunner(p);},materialEventRunner:async p=>{extractCalls++;return extractRunner(p);},sourceReader:async url=>({url,title:'合成来源正文',sourceName:'合成',body,scope:'extracted-text'})});
 const queue=service.researchPipeline;if(queue.snapshot().settings.version===1)queue.configure({version:1,dailyCalls:10,includeClues:false,extractEvents:enable});
 const news={id:digest('pipeline-events-news'),title:'Synthetic company files for bankruptcy',url:'https://example.com/source',publisher:'合成',publishedAt:at};
 const add=()=>{store.ingest([news],at);service.research.process();};
 const step=()=>{service.controlOperation('discovery','resume');return service.runOperation('discovery');};
 const finish=async()=>{const s=queue.snapshot();for(const i of s.items)if(i.runId)await service.modelResearch.wait(i.runId);for(const j of s.events.items)if(j.runId)await (j.kind==='extract'?service.materialEvents:service.modelResearch).wait(j.runId);for(const r of queue.snapshot().relations.items)if(r.runId)await service.semanticEvents.wait(r.runId);return queue.snapshot();};
 const prepare=async()=>{add();await step();await finish();await step();await finish();return queue.snapshot().events.items.find(j=>j.kind==='extract');};
 const choose=(job,index=0,action='create')=>service.materialEvents.decide(job.topicId,job.runId,{eventIndex:index,version:0,action,note:'本人核对合成事项范围'});
 return {store,service,queue,news,packets,add,step,finish,prepare,choose,get modelCalls(){return modelCalls;},get extractCalls(){return extractCalls;},advance(ms){clock+=ms;},async close(){await service.close();store.close();}};
}
test('opt-in extraction proposes multiple events and only a human-selected occurrence gets its own scoped draft',async()=>{
 const f=fixture();try{const book=f.service.paper.snapshot(),job=await f.prepare(),source=f.service.research.get(job.topicId);assert.equal(job.eventCount,2);assert.equal(f.extractCalls,1);assert.equal(f.service.research.list().length,1);await f.step();assert.equal(f.modelCalls,1);assert.equal(f.store.db.prepare('SELECT count(*) n FROM material_event_decisions').get().n,0);
 const created=f.choose(job),child=created.reviews[0][0].topicId;f.choose(job,1,'reject');await f.step();await f.finish();const s=f.queue.snapshot(),draft=s.events.items.find(j=>j.kind==='dossier');assert.equal(draft.topicId,child);assert.equal(draft.status,'candidate');assert.equal(f.modelCalls,2);assert.equal(f.extractCalls,1);assert.equal(s.callsInLast24Hours,3);const p=f.packets[1];assert.equal(p.input.topicId,child);assert.equal(p.input.eventExtraction.eventIndex,0);assert.equal(p.input.eventExtraction.event.quote,quotes[0]);assert.equal(p.input.eventExtraction.runId,job.runId);assert.match(codexPrompt(p),/不把整篇材料的公司、影响或结论投射到当前事项/);assert.equal(f.service.research.get(child).dossier,undefined);assert.equal(f.service.research.get(child).hypothesis.action,'observe');assert.deepEqual(f.service.research.get(job.topicId),source);assert.deepEqual(f.service.paper.snapshot(),book);assert.equal(f.store.db.prepare('SELECT count(*) n FROM research_materials').get().n,1);await f.step();assert.equal(f.modelCalls,2);assert.equal(f.service.research.list().length,2);
 }finally{await f.close();}
});
test('legacy configuration keeps extraction off and changing it does not backfill already scanned items',async()=>{
 const f=fixture({enable:false});try{f.add();f.queue.scan({assertActive(){}});f.queue.configure({version:2,dailyCalls:10,includeClues:false,extractEvents:true});await f.step();await f.finish();await f.step();assert.equal(f.extractCalls,0);assert.equal(f.queue.snapshot().events.items.length,0);const s=f.queue.snapshot().settings;f.queue.configure({version:s.version,dailyCalls:8,includeClues:false});assert.equal(f.queue.snapshot().settings.extractEvents,true);assert.throws(()=>f.queue.configure({version:4,dailyCalls:10,includeClues:false,extractEvents:'true'}),/无效/);
 }finally{await f.close();}
});
