 const f=fixture({extractRunner:async p=>extraction(p,{...decomposition(),events:[]})});try{const j=await f.prepare();assert.equal(j.eventCount,0);await f.step();await f.step();assert.equal(f.extractCalls,1);assert.equal(f.modelCalls,1);assert.equal(f.queue.snapshot().events.items.length,1);assert.equal(f.service.research.list().length,1);}finally{await f.close();}
