 const f=fixture();try{f.add();f.store.db.exec("CREATE TRIGGER reject_plan BEFORE INSERT ON research_pipeline_event_jobs BEGIN SELECT RAISE(ABORT,'synthetic storage failure'); END");await f.step();assert.equal(f.modelCalls,0);assert.equal(f.queue.snapshot().events.items.length,0);assert.equal(f.queue.snapshot().callsInLast24Hours,0);assert.equal(f.store.db.prepare('SELECT count(*) n FROM model_research_runs').get().n,0);f.store.db.exec('DROP TRIGGER reject_plan');f.queue.retry(f.queue.snapshot().items[0].id);await f.step();await f.finish();assert.equal(f.queue.snapshot().events.items.length,1);}finally{await f.close();}
