 for(const change of ['edited','archived','origin']){const f=fixture();try{const j=await f.prepare(),r=f.choose(j),id=r.reviews[0][0].topicId;if(change==='origin'){const run=JSON.parse(f.store.db.prepare('SELECT payload FROM material_event_runs WHERE id=?').get(j.runId).payload);run.candidate.decomposition.events[0].title='Altered candidate';f.store.db.prepare('UPDATE material_event_runs SET payload=? WHERE id=?').run(JSON.stringify(run),j.runId);}else f.service.research.update(id,{version:1,...(change==='archived'?{status:'archived'}:{nextEvidence:'本人已编辑研究，请停止自动准备'})});await f.step();assert.equal(f.modelCalls,1);assert.equal(f.queue.snapshot().events.items.find(v=>v.kind==='dossier').status,'invalidated');await f.step();assert.equal(f.queue.snapshot().events.items.length,2);}finally{await f.close();}}
