test('separate services share the extraction lease and restart never repeats a completed child',async()=>{
 const dir=mkdtempSync(join(tmpdir(),'pipeline-event-shared-')),path=join(dir,'fixture.sqlite');let finish,other;const f=fixture({path,extractRunner:p=>new Promise(resolve=>{finish=()=>resolve(extraction(p));})});
 try{f.add();await f.step();await f.finish();other=fixture({path});await f.step();await other.step();assert.equal(f.extractCalls,1);assert.equal(other.extractCalls,0);finish();await f.finish();const j=f.queue.snapshot().events.items[0];f.choose(j);await f.step();await f.finish();f.service.controlOperation('discovery','pause');const before=f.queue.snapshot();await other.close();other=null;await f.close();other=fixture({path});assert.deepEqual(other.queue.snapshot(),before);assert(other.service.operations().tasks.discovery.paused);assert.equal(other.modelCalls+other.extractCalls,0);
 }finally{finish?.();if(other)await other.close();else await f.close();rmSync(dir,{recursive:true,force:true});}
});
test('event retry API enforces source revision, origin, instance and restore checks',async()=>{
 const f=fixture({extractRunner:async()=>{throw Error('synthetic failure');}});try{const j=await f.prepare();f.service.instance={id:'fixture-instance'};const handler=createHandler(f.store,f.service),call=async(headers={},body={})=>{let status;await handler({method:'POST',url:`/api/research-pipeline/events/${j.id}/retry`,headers:{host:'127.0.0.1:4179','content-type':'application/json','x-signal-instance':'fixture-instance',...headers},async *[Symbol.asyncIterator](){yield JSON.stringify(body);}},{writeHead:n=>status=n,end(){}});return status;};assert.equal(await call({'x-signal-instance':'wrong'}),409);assert.equal(await call({origin:'https://example.com'}),403);assert.equal(await call({},{extra:true}),400);f.store.db.prepare("INSERT INTO settings VALUES('restore_review_required','1')").run();assert.equal(await call(),409);f.store.db.prepare("DELETE FROM settings WHERE key='restore_review_required'").run();assert.equal(await call(),200);await f.step();await f.finish();f.store.ingest([{...f.news,title:'Revised bankruptcy report'}],'2026-10-03T01:00:00Z');assert.equal(await call(),400);assert.equal(f.extractCalls,2);}finally{await f.close();}
});
test('backup and restore preserve extraction, human decisions, pending child drafts and old material without model calls',async()=>{
 const dir=mkdtempSync(join(tmpdir(),'pipeline-event-recovery-')),path=join(dir,'source.sqlite'),f=fixture({path});try{const j=await f.prepare();f.choose(j);f.queue.configure({version:2,dailyCalls:2,includeClues:false});await f.step();f.service.controlOperation('discovery','pause');const b=await createBackup(path,join(dir,'backups')),report=await rehearseRecovery(b.directory,join(dir,'drills'));assert(report.passed,JSON.stringify(report));assert.equal(report.original.tables.research_pipeline_event_jobs.count,2);assert.equal(report.original.tables.material_event_decisions.count,1);assert(report.idle.identical&&report.rollback.identical&&report.snapshotUnchanged);assert.equal(report.networkAttempts,0);}finally{await f.close();rmSync(dir,{recursive:true,force:true});}
});
test('two selected occurrences sharing one article retain separate research, input hashes and model drafts',async()=>{
 const f=fixture();try{const job=await f.prepare(),first=f.choose(job,0).reviews[0][0].topicId,second=f.choose(job,1).reviews[1][0].topicId;await f.step();await f.finish();await f.step();await f.finish();const jobs=f.queue.snapshot().events.items.filter(j=>j.kind==='dossier');assert.equal(jobs.length,2);assert(jobs.every(j=>j.status==='candidate'));assert.equal(f.queue.snapshot().callsInLast24Hours,4);const packets=f.packets.filter(p=>p.input.eventExtraction);assert.equal(new Set(packets.map(p=>p.inputHash)).size,2);for(const [i,id] of [first,second].entries()){const p=packets.find(p=>p.input.topicId===id);assert.equal(p.input.eventExtraction.eventIndex,i);assert.equal(p.input.eventExtraction.event.quote,quotes[i]);assert.equal(p.input.evidence.length,1);assert.equal(f.service.research.get(id).dossier,undefined);}assert.equal(f.store.db.prepare('SELECT count(*) n FROM research_materials').get().n,1);await f.step();assert.equal(f.modelCalls,3);assert.equal(f.service.research.list().length,3);}finally{await f.close();}
});

test('automatic recall of an existing selected occurrence compares that occurrence rather than its whole source article',async()=>{
 const comparisons=[];const f=fixture({extractRunner:async p=>extraction(p,{...decomposition(),events:decomposition().events.map((e,i)=>({...e,title:`Synthetic company files for bankruptcy occurrence ${i}`}))}),semanticRunner:async p=>{comparisons.push(p);const fields=side=>({actor:'合成主体',action:'待核',object:'未知',stage:'未知',eventTime:'未知',timeEvidence:{basis:'unknown',quote:'',quoteField:'none'},quote:p.input[side].eventFocus?.quote||p.input[side].body.slice(0,80),quoteField:'body'}),comparison={relation:'related',left:fields('left'),right:fields('right'),reason:'合成范围绑定检验，不是质量评估',missingEvidence:['核验具体事项']},rawOutput=JSON.stringify(comparison);return {status:'candidate',reviewStatus:'unreviewed',comparison,rawOutput,trace:{model:config.model,inputHash:p.inputHash,outputHash:digest(rawOutput)}};}});
 try{const extractionJob=await f.prepare(),childId=f.choose(extractionJob).reviews[0][0].topicId;await f.step();await f.finish();f.store.ingest([{...f.news,id:digest('different-report'),url:'https://example.com/another-source'}],at);f.service.research.process();await f.step();await f.finish();const planned=f.queue.snapshot().relations.items.find(r=>r.target.id===childId);assert(planned);assert.equal(planned.target.kind,'event');for(let i=0;i<3;i++){await f.step();await f.finish();}const p=comparisons.find(p=>p.input.right.id===childId);assert(p,'scoped model comparison actually ran');assert.equal(p.schema,'event-pair-scoped-1');assert.equal(p.input.right.kind,'event');assert.equal(p.input.right.eventFocus.quote,quotes[0]);assert.equal(p.input.right.eventProvenance.eventIndex,0);assert.equal(f.queue.snapshot().relations.items.find(r=>r.id===planned.id).status,'candidate');assert.equal(f.store.db.prepare('SELECT count(*) n FROM semantic_decisions').get().n,0);
 }finally{await f.close();}
});

function scopedComparison(p){const side=k=>({actor:'虚构甲',action:'待核',object:'乙公司',stage:'待核',eventTime:'未知',timeEvidence:{basis:'unknown',quote:'',quoteField:'none'},quote:p.input[k].eventFocus?.quote||p.input[k].body.slice(0,80),quoteField:'body'}),comparison={relation:'followup',left:side('left'),right:side('right'),reason:'合成范围匹配，不是模型质量结论',missingEvidence:['核验']},rawOutput=JSON.stringify(comparison);return {status:'candidate',reviewStatus:'unreviewed',comparison,rawOutput,trace:{model:config.model,inputHash:p.inputHash,outputHash:digest(rawOutput)}};}
async function otherOccurrence(f,{url='https://example.com/other-report',index=0}={}){let t=f.service.research.create({title:'另一份报道',summary:'合成材料'});t=await f.service.research.readMaterial(t.id,{version:t.version,url,stance:'unverified',family:'other',step:'fact',interpretation:'合成'});const m=t.evidence.find(e=>e.materialId),r=f.service.materialEvents.start(t.id,{version:t.version,materialId:m.materialId,revision:m.materialRevision,requestId:crypto.randomUUID()});await f.service.materialEvents.wait(r.id);const d=f.service.materialEvents.decide(t.id,r.id,{eventIndex:index,version:0,action:'create',note:'核对另一份材料的事项'});return f.service.research.get(d.reviews[index][0].topicId);}
test('selected occurrences recall other reports by occurrence scope and automatically compare without article headline overlap',async()=>{
 const packets=[],f=fixture({semanticRunner:async p=>{packets.push(p);return scopedComparison(p);}});try{const target=await otherOccurrence(f),job=await f.prepare(),child=f.choose(job).reviews[0][0].topicId;await f.step();await f.finish();const j=f.queue.snapshot().events.items.find(j=>j.topicId===child);assert.equal(j.relationCoverage.selectedTopics,1);let r=f.queue.snapshot().relations.items.find(r=>r.source.id===child);assert.equal(r.target.id,target.id);assert.equal(r.source.kind,'event');await f.step();await f.finish();r=f.queue.snapshot().relations.items.find(r=>r.source.id===child);assert.equal(r.status,'candidate');const p=packets.find(p=>p.input.left.id===child);assert.equal(p.input.left.eventFocus.quote,quotes[0]);assert.equal(p.input.right.id,target.id);assert.equal(p.schema,'event-pair-scoped-1');assert.equal(f.queue.snapshot().callsInLast24Hours,4);assert.equal(f.store.db.prepare('SELECT count(*) n FROM semantic_decisions').get().n,0);assert.equal(f.store.db.prepare('SELECT count(*) n FROM event_clusters').get().n,0);assert.equal(f.service.research.get(child).dossier,undefined);}finally{await f.close();}
});
